use xiom.io;

type Contact = {
  name: Str;
  phone: Str;
  email: Str;
}

fn Contact.display(self) -> Str {
  return name + " | " + phone + " | " + email;
}

fn Contact.matches(self, search: Str) -> Bool {
  return name == search;
}

fn main() -> Int {
  let alice = Contact{ name: "Alice Chen"; phone: "555-0101"; email: "alice@email.com"; };
  let bob = Contact{ name: "Bob Smith"; phone: "555-0202"; email: "bob@email.com"; };
  let charlie = Contact{ name: "Charlie Park"; phone: "555-0303"; email: "charlie@email.com"; };
  var count = 0;
  if alice.matches("Alice Chen") { count = count + 1; }
  if bob.matches("Alice Chen") { count = count + 1; }
  if charlie.matches("Alice Chen") { count = count + 1; }
  return count;
}
